def get_input(
    self,
    root,
    rel_fnames,
    addable_rel_fnames,
    commands,
    abs_read_only_fnames=None,
    edit_format=None,
):
    self.rule()

    # Ring the bell if needed
    self.ring_bell()

    rel_fnames = list(rel_fnames)
    show = ""
    if rel_fnames:
        rel_read_only_fnames = [
            get_rel_fname(fname, root) for fname in (abs_read_only_fnames or [])
        ]
        show = self.format_files_for_input(rel_fnames, rel_read_only_fnames)

    prompt_prefix = ""
    if edit_format:
        prompt_prefix += edit_format
    if self.multiline_mode:
        prompt_prefix += (" " if edit_format else "") + "multi"
    prompt_prefix += "> "

    show += prompt_prefix
    self.prompt_prefix = prompt_prefix

    inp = ""
    multiline_input = False

    style = self._get_style()

    completer_instance = ThreadedCompleter(
        AutoCompleter(
            root,
            rel_fnames,
            addable_rel_fnames,
            commands,
            self.encoding,
            abs_read_only_fnames=abs_read_only_fnames,
        )
    )

    def suspend_to_bg(event):
        """Suspend currently running application."""
        event.app.suspend_to_background()

    kb = KeyBindings()

    @kb.add(Keys.ControlZ, filter=Condition(lambda: hasattr(signal, "SIGTSTP")))
    def _(event):
        "Suspend to background with ctrl-z"
        suspend_to_bg(event)

    @kb.add("c-space")
    def _(event):
        "Ignore Ctrl when pressing space bar"
        event.current_buffer.insert_text(" ")

    @kb.add("c-up")
    def _(event):
        "Navigate backward through history"
        event.current_buffer.history_backward()

    @kb.add("c-down")
    def _(event):
        "Navigate forward through history"
        event.current_buffer.history_forward()

    @kb.add("c-x", "c-e")
    def _(event):
        "Edit current input in external editor (like Bash)"
        buffer = event.current_buffer
        current_text = buffer.text

        # Open the editor with the current text
        edited_text = pipe_editor(input_data=current_text, suffix="md")

        # Replace the buffer with the edited text, strip any trailing newlines
        buffer.text = edited_text.rstrip("\n")

        # Move cursor to the end of the text
        buffer.cursor_position = len(buffer.text)

    @kb.add("enter", eager=True, filter=~is_searching)
    def _(event):
        "Handle Enter key press"
        if self.multiline_mode and not (
            self.editingmode == EditingMode.VI
            and event.app.vi_state.input_mode == InputMode.NAVIGATION
        ):
            # In multiline mode and if not in vi-mode or vi navigation/normal mode,
            # Enter adds a newline
            event.current_buffer.insert_text("\n")
        else:
            # In normal mode, Enter submits
            event.current_buffer.validate_and_handle()

    @kb.add("escape", "enter", eager=True, filter=~is_searching)  # This is Alt+Enter
    def _(event):
        "Handle Alt+Enter key press"
        if self.multiline_mode:
            # In multiline mode, Alt+Enter submits
            event.current_buffer.validate_and_handle()
        else:
            # In normal mode, Alt+Enter adds a newline
            event.current_buffer.insert_text("\n")

    while True:
        if multiline_input:
            show = self.prompt_prefix

        try:
            if self.prompt_session:
                # Use placeholder if set, then clear it
                default = self.placeholder or ""
                self.placeholder = None

                self.interrupted = False
                if not multiline_input:
                    if self.file_watcher:
                        self.file_watcher.start()
                    if self.clipboard_watcher:
                        self.clipboard_watcher.start()

                def get_continuation(width, line_number, is_soft_wrap):
                    return self.prompt_prefix

                line = self.prompt_session.prompt(
                    show,
                    default=default,
                    completer=completer_instance,
                    reserve_space_for_menu=4,
                    complete_style=CompleteStyle.MULTI_COLUMN,
                    style=style,
                    key_bindings=kb,
                    complete_while_typing=True,
                    prompt_continuation=get_continuation,
                )
            else:
                line = input(show)

            # Check if we were interrupted by a file change
            if self.interrupted:
                line = line or ""
                if self.file_watcher:
                    cmd = self.file_watcher.process_changes()
                    return cmd

        except EOFError:
            raise
        except Exception as err:
            import traceback

            self.tool_error(str(err))
            self.tool_error(traceback.format_exc())
            return ""
        except UnicodeEncodeError as err:
            self.tool_error(str(err))
            return ""
        finally:
            if self.file_watcher:
                self.file_watcher.stop()
            if self.clipboard_watcher:
                self.clipboard_watcher.stop()

        if line.strip("\r\n") and not multiline_input:
            stripped = line.strip("\r\n")
            if stripped == "{":
                multiline_input = True
                multiline_tag = None
                inp += ""
            elif stripped[0] == "{":
                # Extract tag if it exists (only alphanumeric chars)
                tag = "".join(c for c in stripped[1:] if c.isalnum())
                if stripped == "{" + tag:
                    multiline_input = True
                    multiline_tag = tag
                    inp += ""
                else:
                    inp = line
                    break
            else:
                inp = line
                break
            continue
        elif multiline_input and line.strip():
            if multiline_tag:
                # Check if line is exactly "tag}"
                if line.strip("\r\n") == f"{multiline_tag}}}":
                    break
                else:
                    inp += line + "\n"
            # Check if line is exactly "}"
            elif line.strip("\r\n") == "}":
                break
            else:
                inp += line + "\n"
        elif multiline_input:
            inp += line + "\n"
        else:
            inp = line
            break

    print()
    self.user_input(inp)
    return inp

def confirm_ask(
    self,
    question,
    default="y",
    subject=None,
    explicit_yes_required=False,
    group=None,
    allow_never=False,
):
    self.num_user_asks += 1

    # Ring the bell if needed
    self.ring_bell()

    question_id = (question, subject)

    if question_id in self.never_prompts:
        return False

    if group and not group.show_group:
        group = None
    if group:
        allow_never = True

    valid_responses = ["yes", "no", "skip", "all"]
    options = " (Y)es/(N)o"
    if group:
        if not explicit_yes_required:
            options += "/(A)ll"
        options += "/(S)kip all"
    if allow_never:
        options += "/(D)on't ask again"
        valid_responses.append("don't")

    if default.lower().startswith("y"):
        question += options + " [Yes]: "
    elif default.lower().startswith("n"):
        question += options + " [No]: "
    else:
        question += options + f" [{default}]: "

    if subject:
        self.tool_output()
        if "\n" in subject:
            lines = subject.splitlines()
            max_length = max(len(line) for line in lines)
            padded_lines = [line.ljust(max_length) for line in lines]
            padded_subject = "\n".join(padded_lines)
            self.tool_output(padded_subject, bold=True)
        else:
            self.tool_output(subject, bold=True)

    style = self._get_style()

    def is_valid_response(text):
        if not text:
            return True
        return text.lower() in valid_responses

    if self.yes is True:
        res = "n" if explicit_yes_required else "y"
    elif self.yes is False:
        res = "n"
    elif group and group.preference:
        res = group.preference
        self.user_input(f"{question}{res}", log_only=False)
    else:
        while True:
            try:
                if self.prompt_session:
                    res = self.prompt_session.prompt(
                        question,
                        style=style,
                        complete_while_typing=False,
                    )
                else:
                    res = input(question)
            except EOFError:
                # Treat EOF (Ctrl+D) as if the user pressed Enter
                res = default
                break

            if not res:
                res = default
                break
            res = res.lower()
            good = any(valid_response.startswith(res) for valid_response in valid_responses)
            if good:
                break

            error_message = f"Please answer with one of: {', '.join(valid_responses)}"
            self.tool_error(error_message)

    res = res.lower()[0]

    if res == "d" and allow_never:
        self.never_prompts.add(question_id)
        hist = f"{question.strip()} {res}"
        self.append_chat_history(hist, linebreak=True, blockquote=True)
        return False

    if explicit_yes_required:
        is_yes = res == "y"
    else:
        is_yes = res in ("y", "a")

    is_all = res == "a" and group is not None and not explicit_yes_required
    is_skip = res == "s" and group is not None

    if group:
        if is_all and not explicit_yes_required:
            group.preference = "all"
        elif is_skip:
            group.preference = "skip"

    hist = f"{question.strip()} {res}"
    self.append_chat_history(hist, linebreak=True, blockquote=True)

    return is_yes

def prompt_ask(self, question, default="", subject=None):
    self.num_user_asks += 1

    # Ring the bell if needed
    self.ring_bell()

    if subject:
        self.tool_output()
        self.tool_output(subject, bold=True)

    style = self._get_style()

    if self.yes is True:
        res = "yes"
    elif self.yes is False:
        res = "no"
    else:
        try:
            if self.prompt_session:
                res = self.prompt_session.prompt(
                    question + " ",
                    default=default,
                    style=style,
                    complete_while_typing=True,
                )
            else:
                res = input(question + " ")
        except EOFError:
            # Treat EOF (Ctrl+D) as if the user pressed Enter
            res = default

    hist = f"{question.strip()} {res.strip()}"
    self.append_chat_history(hist, linebreak=True, blockquote=True)
    if self.yes in (True, False):
        self.tool_output(hist)

    return res

