                raise FileNotFoundError(f"Could not find file: {path}")
            log_info(f"Reading: {path}")
            json_name = path.name.split(".")[0]
            json_contents = json.loads(path.read_text("utf-8"))

        elif isinstance(path, BytesIO):
            log_info(f"Reading uploaded file: {path.name}")
            json_name = path.name.split(".")[0]
            path.seek(0)
            json_contents = json.load(path)

        else:
            raise ValueError("Unsupported file type. Must be Path or BytesIO.")

        if isinstance(json_contents, dict):
            json_contents = [json_contents]

        documents = [
            Document(
                name=json_name,
                id=str(uuid4()),
                meta_data={"page": page_number},
                content=json.dumps(content),
            )
            for page_number, content in enumerate(json_contents, start=1)
        ]
        if self.chunk:
            chunked_documents = []
            for document in documents:
                chunked_documents.extend(self.chunk_document(document))
            return chunked_documents
        return documents
    except Exception:
        raise

def read(self, pdf: Union[str, Path, IO[Any]]) -> List[Document]:
    try:
        if isinstance(pdf, str):
            doc_name = pdf.split("/")[-1].split(".")[0].replace(" ", "_")
        else:
            doc_name = pdf.name.split(".")[0]
    except Exception:
        doc_name = "pdf"

    log_info(f"Reading: {doc_name}")

    try:
        doc_reader = DocumentReader(pdf)
    except PdfStreamError as e:
        logger.error(f"Error reading PDF: {e}")
        return []

    documents = []
    for page_number, page in enumerate(doc_reader.pages, start=1):
        documents.append(
            Document(
                name=doc_name,
                id=str(uuid4()),
                meta_data={"page": page_number},
                content=page.extract_text(),
            )
        )
    if self.chunk:
        return self._build_chunked_documents(documents)
    return documents

async def async_read(self, pdf: Union[str, Path, IO[Any]]) -> List[Document]:
    try:
        if isinstance(pdf, str):
            doc_name = pdf.split("/")[-1].split(".")[0].replace(" ", "_")
        else:
            doc_name = pdf.name.split(".")[0]
    except Exception:
        doc_name = "pdf"

    log_info(f"Reading: {doc_name}")

    try:
        doc_reader = DocumentReader(pdf)
    except PdfStreamError as e:
        logger.error(f"Error reading PDF: {e}")
        return []

    async def _process_document(doc_name: str, page_number: int, page: Any) -> Document:
        return Document(
            name=doc_name,
            id=str(uuid4()),
            meta_data={"page": page_number},
            content=page.extract_text(),
        )

    # Process pages in parallel using asyncio.gather
    documents = await asyncio.gather(
        *[
            _process_document(doc_name, page_number, page)
            for page_number, page in enumerate(doc_reader.pages, start=1)
        ]
    )

    if self.chunk:
        return self._build_chunked_documents(documents)
    return documents

